{"hypotheses": [
  {
    "name": "Idiosyncratic Skewness-Illiquidity Interaction",
    "mechanism": "Stocks with high idiosyncratic positive skewness (ReturnSkew3F) and high illiquidity (Illiquidity) may be overpriced due to lottery-seeking investor demand, but pricing inefficiency is exacerbated when both traits co-occur. Shorting such stocks while going long their opposites should capture a premium arising uniquely from their joint mispricing, not present in either signal alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ReturnSkew3F"},
        {"weight": 1.0, "primitive": "Illiquidity"},
        {"weight": -1.0, "primitive": "IdioVol3F"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "Illiquidity", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "R&D Capitalization Volatility Blend",
    "mechanism": "Firms with high R&D-to-assets (RDcap) but low short-term realized volatility (RealizedVol) are likely to be underappreciated innovators with stable operations. Combining high RDcap longs with low RealizedVol shorts targets the segment of innovative firms whose stability is not yet priced in.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "RDcap"},
        {"weight": -0.5, "primitive": "RealizedVol"},
        {"weight": 0.5, "primitive": "OrgCap"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.70,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Post-Spin Merger-Driven Reinvestment",
    "mechanism": "Spinoffs (Spinoff) create temporary valuation inefficiencies, especially when the newly independent firms subsequently display high reinvestment as measured by grcapx3y. Going long recent spinoffs with high reinvestment, funded by shorts in low asset growth (AssetGrowth), targets a unique recombination of post-event and organic growth anomalies.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Spinoff"},
        {"weight": 1.0, "primitive": "grcapx3y"},
        {"weight": -1.0, "primitive": "AssetGrowth"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "Spinoff", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Credit Downgrade Inventory Overhang",
    "mechanism": "When firms experience credit rating downgrades (CredRatDG) while simultaneously accumulating inventory (InvGrowth), suppliers and creditors anticipate distress, but analysts may underreact. Combining these two negatives, with a short overlay on AnalystRevision, captures the premium from the slow dissemination of worsening fundamentals.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "CredRatDG"},
        {"weight": 1.0, "primitive": "InvGrowth"},
        {"weight": -0.5, "primitive": "AnalystRevision"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "AnalystRevision", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.60,
    "expected_decay_half_life_months": 12
  },
  {
    "name": "Ownership Breadth-Return Delay Exploiter",
    "mechanism": "Stocks with declining breadth of ownership (DelBreadth) and high price delay (PriceDelayRsq) face slow information diffusion, leading to temporary mispricings. Going long stocks with increasing breadth and faster price adjustment, while shorting the opposite, leverages this underappreciated interaction.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "DelBreadth"},
        {"weight": -1.0, "primitive": "PriceDelayRsq"},
        {"weight": 0.5, "primitive": "ForecastDispersion"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "weaker"},
      {"type": "correlation", "primitive": "ForecastDispersion", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.55,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Deferred Revenue Surprise Propagation",
    "mechanism": "A combination of positive deferred revenue changes (DelDRC) and positive earnings surprise streaks (EarningsStreak) identifies firms with sustainable future growth underappreciated by the market. The mechanism relies on the market’s slow recognition of recurring surprise earnings when prepayments signal robust demand.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "DelDRC"},
        {"weight": 1.0, "primitive": "EarningsStreak"},
        {"weight": -0.5, "primitive": "DownRecomm"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.58,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Option Volume Trend-Breadth Arbitrage",
    "mechanism": "Rising option volume to average (OptionVolume2) alongside shrinking institutional breadth (DelBreadth) suggests speculative retail inflows into stocks that institutions are exiting. A composite that is long where both trends are aligned and short where they diverge profits from dislocations created by retail crowding and institutional withdrawal.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OptionVolume2"},
        {"weight": -1.0, "primitive": "DelBreadth"},
        {"weight": 0.5, "primitive": "ProbInformedTrading"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "opposite_sign"}
    ],
    "expected_annualized_sharpe": 0.62,
    "expected_decay_half_life_months": 10
  },
  {
    "name": "Brand Investment Forecast Disagreement",
    "mechanism": "When companies show high brand investment (BrandInvest) coincident with high analyst forecast dispersion (ForecastDispersion), the market underestimates their optionality and future growth. This premium should be strongest where brand investment is misunderstood, and disagreement is high.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BrandInvest"},
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": -0.5, "primitive": "ExclExp"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "ForecastDispersion", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.56,
    "expected_decay_half_life_months": 27
  }
]}
